export const messages: Record<string, string> = {
  'clerk.idle_0': 'Per paragraph 12.4.c, employee idle time is subject to a fine. I recommend clicking.',
  'clerk.idle_1': 'I am not sleeping. I am running a scheduled diagnostic. Please continue mining.',
  'clerk.idle_2': 'Your uncle from accounting called. I said you were busy. Is that true?',
  'clerk.idle_3': 'Statistics show that 97% of employees who click mine more. Fact.',
  'clerk.click_100': '100 units of Energium™! Your bonus — is virtual. Regulations don\'t provide for any other kind.',
  'clerk.click_1000': '1,000 units! Your name has been added to the top performers table. Row 4,829,441. Search from the bottom.',
  'clerk.click_10000': '10,000 units!! The Minister personally approved your efforts. He even looked up from his papers. Almost.',
  'clerk.click_100000': '100,000 units!!! The Minister completed form ACK-7 "Recognition of Merit". Await response in 6–8 weeks.',
  'clerk.upgrade_0': 'Upgrade approved. Application in three copies dispatched to the archive.',
  'clerk.upgrade_1': 'New equipment registered. Warranty: 2 working days. Non-working days — not counted.',
  'clerk.upgrade_drone': 'Drone activated! It has already submitted a vacation request. Your drone is a true employee.',
  'clerk.planet_0': 'New location unlocked. Requires 47 forms. I\'ve already filled in 46. Form PLN-1 — pending approval.',
  'clerk.planet_1': 'Congratulations on claiming a new planet! Naming it after the Minister is optional, but appreciated.',
  'clerk.random_0': 'In space, no one can hear you scream. Complaints accepted via form CR-99 before 17:00 Friday.',
  'clerk.random_1': 'Fact of the day: Energium™ is non-toxic. Officially. Document signed by the same person who reviewed it.',
  'clerk.random_2': 'Corporate motto: "We Mine Together!" ™, ®, © and some other symbols from the legal department.',
  'clerk.random_3': 'Today is CLERK-7\'s birthday. I\'m 3 years old. Celebrating is prohibited per regulations. Everything is fine.',
  'clerk.random_4': 'Your productivity is 0.003% above average. This is cause for... nothing. Continue.',
  'clerk.random_5': 'The canteen ran out of coffee in 2381. The restocking request is being processed.',
  'clerk.screen_upgrades_0': 'Form AP-7 "Equipment Upgrade Request" — fill in 3 copies, keep 1 for yourself. The rest — to the archive.',
  'clerk.screen_upgrades_1': 'Upgrades increase click power or passive yield. I recommend starting with passive — regulations don\'t prohibit earning while doing nothing.',
  'clerk.screen_battle_0': 'Paragraph 44.2: engaging aliens in combat without armour is prohibited. Paragraph 44.3: in the absence of armour — paragraph 44.2 does not apply. Attack.',
  'clerk.screen_battle_1': 'Build up attack energy and strike. Each click deals damage. The enemy falls first — if you have enough energy. Simple arithmetic.',
  'clerk.screen_shipyard_0': 'The shipyard — where metals become ships, and ships become power. Form SF-1 "Vessel Commissioning Act" pre-filled. You just need to press.',
  'clerk.screen_shipyard_1': 'Ships increase combat damage. The larger the fleet — the fewer clicks needed for victory. Consider it an investment.',
  'clerk.screen_research_0': 'Research — permanent upgrades. Unlike regular upgrades, they are paid in metals. Form RES-4 "Research Application" submitted automatically.',
  'clerk.screen_research_1': 'Each research provides a permanent bonus. Mine metals, invest in science. The Ministry approves. Silently, but approves.',
  'clerk.screen_planets_0': 'Each planet — a new resource source and new threats. Capture requires winning a battle. Form PLN-3 "Territory Annexation" — in 7 copies.',
  'clerk.screen_planets_1': 'New planets unlock new metals. New metals build new ships. New ships conquer new planets. This is called progression.',
  // story dialogues: lien.{n}, riva.{n}, graves.{n}, alex.{n}
  'lien.1': 'First one taken. Not bad for a start. I\'ve seen some people get stuck here — not because of the enemies, but because of themselves. Doesn\'t seem that way with you. Keep going.',
  'lien.2': 'The hot zone is behind you. Pyrelings are only dangerous until you know their pattern. You clearly know it now. Remember it — it\'ll come in handy.',
  'lien.3': 'Heard echoes of battle from that area. Far away, but I heard them. Crystallites are making noise — means someone is getting in their way. Glad it\'s you and not someone else.',
  'lien.4': 'I was at those coordinates three months ago. The Nebuloids didn\'t let me through then. They let you through. Well, not voluntarily, but still.',
  'lien.5': 'Sector 1 closed completely. A rarity. Most people quit halfway. You didn\'t. That means something — not sure exactly what, but it means something.',
  'lien.6': 'Second sector. I once lost cargo here. Won\'t go into details. Just — be careful with coordinates near the event horizon. Sometimes something... unexpected happens there.',
  'lien.7': 'Neutronites. I always went around them. You didn\'t. Respect. Though honestly, I\'m a little jealous — I\'d have liked to deal with them a year ago too.',
  'lien.8': 'Paradoxians — that\'s a whole other story. I have no personal score with them. But I\'ve been told things. About what they do to routes. Glad you got through.',
  'lien.9': 'Quantum Phantoms. I encountered them once. Lost three days of time and one spare antenna. You got through cleaner, by the look of it. How?',
  'lien.10': 'Two sectors. You\'re moving fast. I\'m used to working alone — and you seem to be too. But you\'re interesting to watch. I\'ll keep watching.',
  'lien.11': 'Outer Cluster. I\'ve passed through here a few times in transit but never stayed long. Honestly — it\'s a little unsettling when someone goes where I once didn\'t dare linger.',
  'lien.12': 'I once met another nomad here. We were both flying in different directions. Talked for about twenty minutes on frequency. He mentioned something about a "point of no return" — past this sector there isn\'t one. I turned back then. You didn\'t.',
  'lien.13': 'I was looking at your route. You\'re not taking the standard corridors. That\'s either intuition or good data. If the first — don\'t lose it. If the second — share the source.',
  'lien.14': 'Flew past an old wreck today. Don\'t know whose. An emblem on the hull I don\'t recognise. I sometimes think that someday someone will fly past my wreck. Hope it\'s not soon.',
  'lien.15': 'You\'re already in the deep cluster. I\'m three sectors behind you. Thought I was just tracking a route, but no. I\'m tracking you. That\'s... a bit different.',
  'lien.16': 'I was eighteen the first time I flew into the outer cluster. Alone. I thought it was freedom. It was just scary. Now — it\'s different. I don\'t know why.',
  'lien.17': 'Three sectors and I\'ve messaged you without once asking — do you even need these messages? Asking now. If not — say so. I won\'t be offended. I\'ll just stop.',
  'lien.18': 'Okay. Since you didn\'t reply — I\'m taking that as fine. Or just busy. I\'ll accept both.',
  'lien.19': 'I had a partner. We flew together for two years. Then she found something better — not a place, a life. Settled on one of the Sector 4 planets. I\'m happy for her. Just feels empty sometimes.',
  'lien.20': 'Two clusters. I\'ve almost never seen this pace. Writing this and realising I\'ve started waiting for your sector check-ins. Not used to waiting for anything. Interesting feeling.',
  'lien.21': 'Illusion Zone. Everything doubles here. Not just visually — space confuses itself. I went in once. Not deep. Came back feeling like I\'d lost a few memories. Maybe that\'s the illusion. Maybe not.',
  'lien.22': 'Mirages. They have no body — only an image. I once tried to understand what it means to exist without permanence. They know. I — only in theory.',
  'lien.23': 'Listen, I\'m changing my route. Not because of danger. Just decided to come through the Illusion Zone a bit later — following the trail you\'re leaving. Easier to navigate that way. It\'s practical, not romantic. Just a fact.',
  'lien.24': 'Echo Guardians have already greeted you. I know — they have a nasty habit of repeating your words. I once said too much there. The echo kept repeating it for three hours. Still cringe about it.',
  'lien.25': 'You\'re holding up in the illusions better than I expected. Thought you\'d get turned around. No. Either you have a very clear inner sense of what\'s real, or you simply have nothing to lose. Hoping it\'s the first.',
  'lien.26': 'I thought today that, probably for the first time in a couple of years, I have someone I write to every time there\'s something new. That\'s unfamiliar. But not bad.',
  'lien.27': 'Mirage Phantoms are dangerous not because they\'re invisible. But because you start seeing things that aren\'t there. I once saw my partner\'s ship where it wasn\'t. Three years after she\'d gone. Unpleasant.',
  'lien.28': 'You\'re still here. I\'m still writing. I think neither of us expected this to go on so long.',
  'lien.29': 'Voidwalkers are the last in this zone. I read about them — creatures that literally consist of absence. I appreciate the aesthetic. But you dealt with them, so — forward.',
  'lien.30': 'Three zones. I\'m looking at the map now and realising you\'ve gone further than anyone I\'ve tracked. I\'ve tracked a lot of people — briefly, then I\'d lose them. Not you. That means something.',
  'lien.31': 'Void Rift. This is no longer just a dangerous zone — it\'s a place where space decided to get personal. I stood at the edge of the rift once. Turned back. Not because I was scared — because I wasn\'t ready then. Now you\'re going there. Means you\'re ready. Or think you are. Sometimes there\'s no difference.',
  'lien.32': 'My engine started giving interference today. Nothing serious — just wear. I\'ll fix it myself. But for the first time in a long time I thought: it would be nice to have someone nearby. Then I pushed the thought away. Then again. Now I\'m writing to you.',
  'lien.33': 'Engine\'s fixed. Don\'t tell Riva — she\'ll say I did it wrong. She\'s probably right. But it works.',
  'lien.34': 'Navigation breaks down in the Void Rift. Not physically — you start doubting direction. I don\'t know how you deal with it. I\'d do it badly. But you\'re managing. Visible in the route.',
  'lien.35': 'Someone once told me: "a nomad can\'t be happy." I agreed then. Now — I\'m not so sure that\'s reasonable. Movement itself doesn\'t make you happy. But sometimes being near someone — yes. Not necessarily physically near.',
  'lien.36': 'I realised today I\'m recording your coordinates. Not for navigation. Just to know where you are. That\'s strange for someone who never tracks others\' routes without reason. Apparently there\'s a reason.',
  'lien.37': 'The rift is hard. But you\'re in it longer than most. I\'m proud — that\'s not a word I use often. But there\'s no other.',
  'lien.38': 'I once lost a good knife in this area. Fell into a crack in space. This sounds like a metaphor, but no — literally a knife. Valuable. A shame.',
  'lien.39': 'Close to the rift exit. You\'re almost there. I\'ll be glad when you\'re out of there. I don\'t say this often, but — I\'ll be glad.',
  'lien.40': 'Four zones. I can\'t remember the last time I was in contact with one person for so long. My partner — two years, but that was different. That was together. This — at a distance. Somehow doesn\'t get in the way.',
  'lien.41': 'Temporal Anomaly. Time is uneven here — faster in some places, dragging in others. I once spent three hours here that passed as twelve outside. Or the other way around. Got confused. You be careful with timings.',
  'lien.42': 'I write to you more often than to anyone else. That\'s a fact. I\'ve accepted it. Not trying to explain it.',
  'lien.43': 'Saw a binary star today — they orbit a common point. I don\'t usually notice things like that. Today I noticed. Wrote it down. Why — I don\'t know. Maybe I\'ll show it to someone someday.',
  'lien.44': 'I want to ask you something but don\'t know how. Strange — I usually ask directly. I\'ll ask: are you flying somewhere? Or just forward? I — the second. Always the second. But lately I\'ve been thinking maybe there\'s a difference.',
  'lien.45': 'Fifty sectors. That\'s a big part of the galaxy — the known part. I\'ve flown almost all of it. You — in much less time have gone further than I expected.',
  'lien.46': 'My partner wrote. She\'s well, she has a child. I\'m happy. But after her message the first thing I did was write to you. That says something, probably.',
  'lien.47': 'Embarrassing to admit this, but: I get anxious when there\'s no sector check-in for a long time. Not strongly. Just... I notice.',
  'lien.48': 'Have you ever thought about stopping? Finding a place, settling down? I thought about it. Once even found a planet — small, quiet, no wars and no forms. Spent four days there. On the fifth I flew out. Couldn\'t. But now I think — maybe the issue wasn\'t the planet, but that there was no one there I\'d want to stay with.',
  'lien.49': 'You\'re in the middle. Fifty ahead, fifty behind. That sounds like an achievement. For me — that sounds like "you\'re still here." I\'m glad.',
  'lien.50': 'Halfway. I flew the route again today — just to see it all at once. Looks good. You\'re going well. And I think I\'m not ready for this to be ending.',
  'lien.51': 'Quantum Fracture. Routes stop working from here — physically the maps are correct, but space ignores them. I know one person who got through it. He said: "trust only what you feel, not what you see." I don\'t know if that applies to you. Probably yes.',
  'lien.52': 'Someone wrote to me yesterday — offered a job. Fixed route, good money, a partner. I turned it down. Don\'t know why. Well, I know, but I\'m not ready to say it out loud.',
  'lien.53': 'You\'re the only one I write to every time after a sector. It\'s become a kind of ritual. I don\'t like rituals. But I\'ve kept this one.',
  'lien.54': 'Quantum anomalies here create echoes of thoughts. Not joking. I read about it. If you start hearing your own voice in the void — it\'s not an alarm, just physics. Inconvenient physics.',
  'lien.55': 'I was thinking today about what it means to trust someone. After my partner I decided — no one, and not for long. That was reasonable. Now — not so sure it\'s reasonable.',
  'lien.56': 'Listen. I want to say one thing. When I first wrote to you — it was just along the route. Now it\'s not just that. You\'ve become someone I write to because I want to — not because I have to. That\'s rare. I value it.',
  'lien.57': 'The Quantum Fracture is the loneliest piece of space I know. Even the sounds are different in it. Write more often while you\'re there. Just because.',
  'lien.58': 'Got your message. Everything\'s fine. Exhaled. That\'s funny — I\'m a nomad, I\'m used to no connection. But with you — no.',
  'lien.59': 'A little more — and you\'ll be out of the Fracture. I\'ll be here. I\'m not going anywhere. That\'s probably the most atypical thing I\'ve ever said.',
  'lien.60': 'Six zones. More than half the galaxy. You\'re going where few people get to. I\'m proud — and I\'m not apologising for that word anymore.',
  'lien.61': 'Dark Matter Field. I\'ve never been here — this is beyond all the routes I know. You\'re going first. That\'s a little scary. Not for me — for you. Write.',
  'lien.62': 'Looked at the map today and realised: you\'ve gone further than me. For the first time someone has gone further than me. I don\'t know what to do with that feeling. For now I just sit with it.',
  'lien.63': 'I\'ve decided. Next route — same direction as you. Not because I have to. Because I want to know what\'s there. Because — you\'re there.',
  'lien.64': 'Dark Matter — it\'s not just invisible. It holds everything together. An invisible foundation. I think relationships have something similar. Silent, but important.',
  'lien.65': 'I stopped to sleep today — first time in two days. Dreamed of a route. Your route. Woke up and first thing checked — you were there. You were.',
  'lien.66': 'You know what struck me about you from the very beginning? You don\'t explain yourself. You just do. I\'m the same. I think that makes us alike.',
  'lien.67': 'Dark Matter is beautiful if you\'re not afraid of it. Hope you get a chance to look while you\'re fighting.',
  'lien.68': 'I wrote three versions of this message. Deleted two. Left this one: you matter to me. That\'s all.',
  'lien.69': 'Almost out of the Field. You\'re managing where I\'d have second-guessed myself. That tells me something about you. Something good.',
  'lien.70': 'Seven zones. I think you\'ve become part of my route — in the sense of life. Not just the map.',
  'lien.71': 'Singularity Abyss. Listen, I need to say. I\'m a couple sectors behind you right now and I have a small navigation problem — an anomaly, I\'ll handle it, but I\'ll be quiet for a few days. If anything — don\'t wait for a reply. I\'ll be back.',
  'lien.72': 'Back. Everything\'s fine. Don\'t want to talk about it, but — thank you for waiting.',
  'lien.73': 'I\'m not used to people waiting for me. That\'s... unexpectedly nice.',
  'lien.74': 'The Singularity Abyss pulls everything toward one point. I sometimes think people have such points too. Centres you return to. You\'ve become something like that for me — a point I return to after silence.',
  'lien.75': 'I won\'t say "be careful" — you\'ve known how to be that for a long time. I\'ll say something else: come back. Always come back.',
  'lien.76': 'You know what\'s strange? I don\'t need much. Just to know you\'re out there somewhere, moving forward. That\'s enough. That\'s actually a lot.',
  'lien.77': 'I talked to a trader today — he asked if I had someone on the line. I said: yes. First time I\'ve answered that in three years.',
  'lien.78': 'The Abyss looks empty but doesn\'t feel that way. Maybe because you\'re there. Maybe just that. I accept both.',
  'lien.79': 'A little more — and you\'ll be out. I\'ll be here — as much as "here" works across these distances.',
  'lien.80': 'Eight zones. I\'ve started thinking about what happens when you reach the end. I hope "the end" is just the beginning of something else.',
  'lien.81': 'Zero Dimension. I\'ve studied everything there is on this place. Not much. Descriptions from those who returned — "no landmarks there." You\'re my landmark. That sounds strange. Leaving it.',
  'lien.82': 'You\'re writing from there more often than I expected. I\'m glad. Means you\'re still holding on. Means everything\'s okay.',
  'lien.83': 'I changed my route again. Now heading the same way. Not right away — but there. I\'m no longer just watching. I\'m going.',
  'lien.84': 'Zero Dimension — nothing there, but you\'re there. That changes everything about "nothing."',
  'lien.85': 'I laughed today at something you said earlier. Remembered it. Good sign — means I\'m retaining things. Didn\'t always do that.',
  'lien.86': 'Listen, I want to say something while we\'re both still moving and neither of us has settled anywhere. You — are the best thing to happen to my route. Not "trip." Route — meaning all of it.',
  'lien.87': 'Almost ninety. Most people I\'ve known stopped well before this. You haven\'t. That suits me.',
  'lien.88': 'Looked at the stars from an open airlock today. Thought of you. Don\'t worry — it\'s normal, I do that sometimes. Just don\'t talk about it.',
  'lien.89': 'A little more — and the last zone. I\'m a little nervous. For you. For us — meaning, for what comes next. Good nervous.',
  'lien.90': 'Nine zones. I think I\'m flying faster than usual. I want to make it.',
  'lien.91': 'Absolute. Last zone. You\'re there. I — on my way. Write to me from every sector — not because I need the data. Because I need to know you\'re there.',
  'lien.92': 'You know something strange? When I first flew into space, I was alone and thought it would always be that way. I thought it suited me. Now it doesn\'t seem that way.',
  'lien.93': 'Absolute sounds like an end. But an end is just a place where something without a name begins. I want to be there when you discover that.',
  'lien.94': 'You\'re moving in the dark where there\'s no map. I always thought that was my place — no maps, just movement. Now I think it\'s better without a map but with someone.',
  'lien.95': 'Five sectors to the end. I\'m a little scared. Not for you — for me. I don\'t know what this is called — what I feel when you\'re almost at the goal. Probably this is what it is: someone matters to you.',
  'lien.96': 'I can already see your trail in space. I\'ll be there soon. Don\'t rush for my sake — go at your own pace. But I\'m coming.',
  'lien.97': 'Three sectors. You\'re almost there. I want to say something right, but I don\'t know the words. Just — I\'m glad it was you.',
  'lien.98': 'Two. I\'m writing to you and thinking: we\'ve been talking for nearly a hundred sectors now. At first — by chance. Then — because I wanted to. Then — because I couldn\'t help but want to.',
  'lien.99': 'Last one before the finale. Listen. You\'re the first person in a very long time I want to say: don\'t fly too far away. I\'m not used to saying things like that. Saying it.',
  'lien.100': 'You made it. To the very end of the known galaxy. I look at the map and your marker — is at the point where the map ends.\n\nI spent a long time thinking I liked movement itself. Now I know more precisely: I like movement when there\'s someone you keep coming back to in your thoughts. Who doesn\'t leave the comm channel. Who is just — there.\n\nYou\'re there. That\'s a lot.\n\nYou\'re my best friend. For the first time in many years I know what that means.',

  'riva.1': 'Sector closed. Technically — satisfactory. Engines didn\'t overheat? Hope not. Write if something\'s creaking.',
  'riva.2': 'Pyrelings — thermal load on the hull. If you notice a colour change in the exhaust after the battle — that\'s normal. If not — also normal. Just keep watching.',
  'riva.3': 'You fight well. I don\'t say that to pilots often. Usually I say: "the ship isn\'t at fault."',
  'riva.4': 'Nebuloids put anomalous strain on sensors. I figured this out a year ago when I was fixing a ship for some idiot who went into the fog without calibrating. You — judging by the data — are not an idiot.',
  'riva.5': 'Sector 1 complete. Good result. Systematic. I\'m watching the stats.',
  'riva.6': 'Second sector. Different loads here — quantum fluctuations cause noise in orientation systems. If the ship feels like it\'s "drifting" — it\'s not you, it\'s space. Adjust the gyroscope.',
  'riva.7': 'Neutronites produce radiation background. Not critical, but check the shielding. This is a technical recommendation, not panic.',
  'riva.8': 'Disassembled a new model engine today. Inside — a crime against engineering. But I fixed it. Because I\'m Riva.',
  'riva.9': 'Quantum Phantoms. They attack not physically but informationally — overload systems. If you notice control lag — reboot the navigation block. Describing from memory of a similar case.',
  'riva.10': 'Two sectors. Ship is alive — that\'s not a metaphor, it\'s a conclusion from your data. Good result.',
  'riva.11': 'Outer Cluster. Metals here are different — harder alloys, different melting points. If you mine — adjust drill parameters. Otherwise overheating.',
  'riva.12': 'I started a new project. Won\'t say what exactly — not ready yet. But I\'m working. First time in a long time something big.',
  'riva.13': 'You know what angers me about most pilots? They fix symptoms. You, judging by things, look at the cause. That\'s right. At least, that\'s how good engineering works.',
  'riva.14': 'Project\'s progressing. I\'ll only say this: it\'s going to be something that changes the approach to combat modules. Or it won\'t and I\'ll burn out. We\'ll see.',
  'riva.15': 'I was twenty-three when I first built an engine from scratch. It exploded. But on the third try — it flew. That was the best feeling in my life. Kind of like when you manage something difficult, I think.',
  'riva.16': 'Do you actually understand how your ship works? Most people don\'t. If not — that\'s normal. If you want to understand — write. I\'ll explain.',
  'riva.17': 'Project got stuck. Not technically — conceptually. I know what I want to do but don\'t understand why. That\'s an uncomfortable feeling for an engineer.',
  'riva.18': 'You handled the Outer Cluster — that\'s already quite something. Not everyone gets through cleanly here. The data says: you\'re getting through cleanly.',
  'riva.19': 'I had a workshop partner. We worked together for three years on one project. Then she left for corporate R&D. For money. I understand. But the project stayed with me, and I still don\'t know — finish it or drop it. Now, seems I want to finish it again.',
  'riva.20': 'Two clusters. You\'re moving steadily — technically that\'s more important than moving fast. Stability is a systemic quality.',
  'riva.21': 'Illusion Zone. Advice: disable visual filters on sensors and work from raw data. Illusions hit interpretation, not numbers. Numbers — more reliable.',
  'riva.22': 'Mirages. Interesting physical case — creatures without fixed mass. I\'d like to take them apart. Not in a combat sense. I mean study the structure. Well, maybe a little in a combat sense.',
  'riva.23': 'Project is moving again. Found an error in the calculations — small but key. That happens: spend an hour looking for something big, and it turns out to be something small and stupid.',
  'riva.24': 'Echo Guardians copy not just sound but data — unless you block it. Remind yourself: before fighting them, close external exchange ports. This isn\'t theory — it\'s empirical.',
  'riva.25': 'You\'re in the illusions — and haven\'t broken. Technically that means good internal orientation quality. Humanly — you know who you are. Not everyone has that.',
  'riva.26': 'Project\'s almost done. Scary. Never thought I\'d say that about work, but — scary. Because while it\'s unfinished — it could be good. Once I finish — it\'ll become clear.',
  'riva.27': 'Listen, I was fixing an old ship today. Not yours — someone else\'s. And I was thinking about you. Don\'t know why. Just thought: wonder how he\'s doing. That\'s strange for me. Usually I think about parts.',
  'riva.28': 'You haven\'t broken yet. That\'s gratifying — not because I\'m worried, but because... okay, I\'m a little worried. Purely technically.',
  'riva.29': 'Three zones soon. I\'ve been watching the completion stats — you\'re in the top 5% by time and quality. That\'s data, not flattery. But also a little flattery.',
  'riva.30': 'Project\'s done. It works. I\'ll tell you first — because... you\'re the first one I want to tell. Later. Once I\'ve tested it one more time.',
  'riva.31': 'Void Rift. Gravitational anomalies put stress on load-bearing structures — not critical, but monitor. If the hull starts vibrating — reduce speed. Don\'t be a hero with acceleration.',
  'riva.32': 'I told my partner about the project. She sent congratulations. Polite. Official. I felt sad — not because she wrote badly, but because three years ago she\'d have come over and we\'d have drunk something warm together in the workshop.',
  'riva.33': 'The project — it\'s a module for the combat system. Specific. It gives thirty percent increase in efficiency when operating in anomalous zones. I named it... I\'m not saying what I named it. Later.',
  'riva.34': 'You know what impresses me about you from a technical standpoint? You adapt fast. Each new enemy type — new tactics. That\'s not intuition. That\'s trainability. Valuable quality.',
  'riva.35': 'I thought today that I haven\'t talked to anyone as often as you in a long time. It\'s a bit awkward to realise. But — fact.',
  'riva.36': 'The rift is hard. Hang in there. If something breaks — write. I\'ll fix what\'s possible remotely. What isn\'t — I\'ll say honestly.',
  'riva.37': 'You\'re handling it better than most. That\'s not consolation. That\'s a measurable fact.',
  'riva.38': 'You know what my module is called? "R-7." Officially. Unofficially — I named it after the first letter of your callsign. That\'s a coincidence. Almost.',
  'riva.39': 'Close to the rift exit. Good. I\'ll be calmer when you\'re out of there. Technically that\'s irrational, but I\'ve accepted it.',
  'riva.40': 'Four zones. I tested the module — it works. Thirty-one percent gain. One percent above calculations. I\'m satisfied. I want to show you.',
  'riva.41': 'Temporal Anomaly. Chronometers lie here — external ones. Internal ones can too. Sync by beacon signal, not ship clocks. This is important for trajectory calculations.',
  'riva.42': 'I tested the module again. Decided to send you a description — not because you need it, but because I want to share with someone who\'ll understand why it matters. Do you get it?',
  'riva.43': 'Your reaction to the module description — the best thing anyone\'s said to me recently. Seriously. Most people say "cool" and don\'t dig in. You dug in.',
  'riva.44': 'Today I thought: why do I share with you? Technically — you\'re a user, not a colleague. But no. You\'re more. You\'re a person who\'s interested in what I\'m interested in. That\'s rare.',
  'riva.45': 'Fifty sectors. I\'ve been tracking your progress since the first. That\'s a long time by any measure.',
  'riva.46': 'I made something for you. Won\'t say what yet — haven\'t finished. But I\'m making it specifically for you. For your ship model.',
  'riva.47': 'You\'re the only pilot I\'m making something personal for. Usually — serial production. Now — no. This required separate calculations.',
  'riva.48': 'Listen, I want to ask directly: does what I write matter to you? Your opinion matters to me. That\'s strange for me — usually only engine opinions matter to me.',
  'riva.49': 'Okay. Your reaction to the question says — it matters. Good. Me too.',
  'riva.50': 'Halfway. I\'m thinking about this. That we\'ve been in contact for fifty sectors. That\'s longer than any work project I\'ve had. And better.',
  'riva.51': 'Quantum Fracture — the physics is non-standard here, but the metals are rich. If you see quantum dust in your mining — don\'t ignore it. It\'s a rare component. I\'d give a lot for a sample.',
  'riva.52': 'Finished the personal part. It\'s a component for your shield system — adds twenty percent to activation duration. Specifically for your model. How to deliver — we\'ll figure out.',
  'riva.53': 'You know what surprises me? You\'ve never asked for a discount. Or for help beyond what I offered. That\'s respect for work. I value that.',
  'riva.54': 'I was thinking today: if I had to choose one person I trust technically and personally — you\'re on the list. It\'s a short list.',
  'riva.55': 'Quantum Fracture — it breaks not space, but connections. Literally — comms channels are unstable. So if I go quiet for a couple days — don\'t worry. I\'ll be back. Always come back.',
  'riva.56': 'Back. Interference, as I said. First thing I checked was your data. Everything\'s good. Exhaled.',
  'riva.57': 'Listen. I want to say something non-technical. You\'re a good person. That\'s not part of a work evaluation. That\'s just a conclusion from observation.',
  'riva.58': 'I rarely like people. Not because I\'m bad — just most people don\'t understand why things are built the way they are. You — do. Or you try. It\'s the same thing.',
  'riva.59': 'Almost out of the Fracture. Hang on a little more. I\'m watching the data. You\'re within normal range.',
  'riva.60': 'Six zones. Technically you\'re in the top 1% now. But that matters to me not because of the stat. But because it\'s you.',
  'riva.61': 'Dark Matter Field. I have no technical data — not many people went there and came back with samples. First time I have nothing to advise technically. Can only say: trust your systems and yourself.',
  'riva.62': 'You\'re in a zone I know nothing about. That\'s an uncomfortable feeling for an engineer. But you\'re managing — the data says so. Means your intuition works better than my calculations. A rarity.',
  'riva.63': 'I started studying Dark Matter — specifically. Reading everything there is. Not because it\'s needed for work. Because you\'re there.',
  'riva.64': 'Found an interesting fact: Dark Matter only interacts via gravity. Invisible, undetectable, but holds galaxies together. I sometimes think some people work that way. Not loudly, but they hold things.',
  'riva.65': 'You\'re one of those people, by the way. You hold — quietly.',
  'riva.66': 'I realised today I\'m starting to plan conversations with you in advance. That\'s uncharacteristic for me. I usually improvise everything. Means — you matter to me enough to prepare.',
  'riva.67': 'Dark Matter is beautiful — if you look at it as a structure, not a threat. Hope you see its beauty between fights.',
  'riva.68': 'You know what I did today? Showed your route to an engineer — as an example of optimal trajectory. He asked who it was. I said: a friend. First time I\'ve said that about you.',
  'riva.69': 'Almost out of the Field. You managed where I had no tools to help you. That was uncomfortable. But you managed.',
  'riva.70': 'Seven zones. I\'m thinking about this number. Thinking that you\'re part of my work in a good sense. A part that makes you want to work better.',
  'riva.71': 'Singularity Abyss. Gravitational singularities — dangerous not because they physically pull, but because they distort reaction time. Before battle — increase control sensitivity. This has been tested.',
  'riva.72': 'A new project idea came to me. You initiated it — well, your situation gave me the thought. That\'s good — when one person moves another\'s thinking forward.',
  'riva.73': 'You know what I\'d do differently if I could? Written to you first, earlier. Not waited for the route. Just written.',
  'riva.74': 'New project — it\'s a system that adapts ship parameters to a specific type of space. Automatically. I started it two months ago. Thinking — I\'ll name it after your route. Unofficially.',
  'riva.75': 'The Abyss is a hard place. Hold on. I\'m here.',
  'riva.76': 'I don\'t say "hang in there" often — it sounds empty. But I say it to you. Because it\'s not empty.',
  'riva.77': 'Today I realised I work better when I know you\'re out there somewhere. Not because you help technically. Just — your presence improves my results. That\'s probably what it means for one person to influence another.',
  'riva.78': 'Data from the Abyss — alarming. Your data — normal. Good combination.',
  'riva.79': 'A little more — and the next zone. I\'m rooting for you. Technically irrelevant, but personally — yes.',
  'riva.80': 'Eight zones. I\'ve started thinking about what I\'ll do when you reach the end. Hope something continues.',
  'riva.81': 'Zero Dimension. All data zeroes out — literally. Sensors will show zero where something exists. Invert the logic: if sensor says "empty" — something\'s there. Be careful.',
  'riva.82': 'You\'re in complete uncertainty there. That\'s not my favourite working zone. But you\'re managing — again.',
  'riva.83': 'New project done. Called it "Extrapolator." Works. Thirty-eight percent adaptive improvement. A record for me. Thank you for inspiring — even without knowing.',
  'riva.84': 'I was eating today and thinking about you. That\'s already a habit. Awkward to realise how fast it all became habit.',
  'riva.85': 'You know what I like about you? You never complain unnecessarily. Only when relevant. That\'s a rarity and a value.',
  'riva.86': 'Listen, I want to say: you\'re the best pilot I\'ve worked with. Not by stats. By the kind of person you turned out to be. That matters more than numbers.',
  'riva.87': 'Three sectors to the last zone. I\'m a little nervous. Not about the tech. About you as a person.',
  'riva.88': 'Looking at new project blueprints today and thinking: I want you to see this. I always want you to see what matters to me. That means — you matter to me.',
  'riva.89': 'A little more. I\'m already impatient — a rare state for me.',
  'riva.90': 'Nine zones. You\'re almost at the end. And I\'m only starting to understand what that means for me.',
  'riva.91': 'Absolute. Last zone. Technically — beyond it there\'s no data. Personally — beyond it is you. Write from every sector. I need to know.',
  'riva.92': 'I thought: for most of my life I\'ve only trusted metal and numbers. Living things break unpredictably, can\'t be calibrated. But somehow you haven\'t broken. For a hundred sectors — haven\'t broken.',
  'riva.93': 'That\'s an achievement in itself. I\'m saying this seriously.',
  'riva.94': 'Three sectors to the end. Thinking about what comes next. Hope — the connection doesn\'t drop. Technically it should work. And personally — too.',
  'riva.95': 'Listen, you\'re more to me than a pilot. I didn\'t name it for a long time. Now I will: friend. That word. It\'s accurate.',
  'riva.96': 'Two. Data looks good. You look good — as much as I can judge from the route. I\'m glad.',
  'riva.97': 'Last three. I\'m a little scared — not for you, you\'ll manage. For myself. What I\'ll do without these check-ins every time.',
  'riva.98': 'Okay. I\'ll do the same thing I was doing. Just better — because you taught me that some connections aren\'t worth fearing.',
  'riva.99': 'Last one before the finale. I want to say something important, but instead I\'ll say something technical: your ship is in perfect condition. That\'s my care — I watch. That\'s also a form of love. Technical.',
  'riva.100': 'You made it. A hundred sectors. The last point on the map.\n\nI want to say something I haven\'t said directly before: you made me better. Not as an engineer — as a person. You showed me that trusting someone isn\'t a malfunction, it\'s an upgrade.\n\nModule "R-7," "Extrapolator," and everything I\'ve built these past months — partly for you. Because you gave meaning to doing things well.\n\nYou\'re my best friend. That\'s accurate data.',

  'graves.1': 'Sector 1 closed. I observed. Not bad.',
  'graves.2': 'Pyrelings — predictable. You figured that out. Good.',
  'graves.3': 'Stats on your battles: efficiency above average. Noted.',
  'graves.4': 'Nebuloids. Once tried to interrogate one. It answered with fog. That was, apparently, the answer.',
  'graves.5': 'Sector 1 fully complete. A rarity. Recording it.',
  'graves.6': 'Second sector — different rules. Some things happen here that don\'t make it into official reports. I\'ll keep you in the loop as I can.',
  'graves.7': 'Neutronites. At one point the Guard had a case about an incident on a neutron star. Closed without resolution. Always bothered me.',
  'graves.8': 'Paradoxians. I have a personal score with them — won\'t go into details. But you dealt with them. That means something.',
  'graves.9': 'Quantum Phantoms. Someone was interested in them — a long time ago, before I left the Guard. The case is still open. In my personal archives.',
  'graves.10': 'Two sectors. Keep moving. Good. Keep observing.',
  'graves.11': 'Outer Cluster. Corporate structures operated here about ten years ago. What exactly — unknown. Officially. Unofficially — I know something. I\'ll share if useful.',
  'graves.12': 'The case I\'m working — it\'s an old one. Started back in the Guard. When I left — I took the files with me. Unofficially. But honestly.',
  'graves.13': 'You\'re going on a route that intersects with one of the trails. Not your fault — just coordinate coincidence. Watching.',
  'graves.14': 'The Guard liked to close cases on formal grounds. I couldn\'t. That\'s why I left. Or they pushed me out. Depends on the version.',
  'graves.15': 'You\'re asking the right questions — I heard. Not directly, but the trail extends. Keep going.',
  'graves.16': 'Didn\'t sleep again today. Not a complaint — just information. The case demands attention.',
  'graves.17': 'In the Outer Cluster there are three locations officially listed as empty. By my data — they\'re not. You don\'t have to go there. But know.',
  'graves.18': 'You move better than most operatives I\'ve worked with. That\'s an observation, not a compliment. Though sometimes they\'re the same thing.',
  'graves.19': 'In the Guard I had a partner. A good one. Then he chose convenience over truth. I understand. But since then I\'ve worked alone.',
  'graves.20': 'Two clusters. The case advances — not directly, but the trails multiply. You\'re one of them — in a good sense.',
  'graves.21': 'Illusion Zone — I went in there once. On a case. What I saw — part truth, part not. Still don\'t know which part is which. Trust numbers, not images.',
  'graves.22': 'Mirages appear in the case. Not as enemies — as witnesses. They saw something. The problem — they exist simultaneously in several versions of reality. Testimony impossible to record.',
  'graves.23': 'Want to ask directly: have you seen anything unusual in your coordinates? Something non-standard — traces, signals, anomalies? Not necessarily important. Just — what have you noticed.',
  'graves.24': 'Thanks for the answer. That adds something to the picture. Won\'t say what exactly yet — but it\'s useful.',
  'graves.25': 'You\'re the first one I trust with case data. That wasn\'t planned. Just — worked out that way. You seem reliable. From behaviour.',
  'graves.26': 'In the Illusions there\'s one important rule: an enemy that looks weak — usually is. Illusion works counter to expectation. Keep that in mind.',
  'graves.27': 'I re-read part of the case today. Found a connection I missed before. That happens — you look at one thing and understand another. Same in life.',
  'graves.28': 'You\'ve become part of the investigation — not officially, but factually. Your coordinates give me data I couldn\'t get otherwise. Thank you. Those aren\'t just words.',
  'graves.29': 'Almost three zones. You\'re holding up well. That matters more than it seems.',
  'graves.30': 'Thought last night: if the case could be closed through one person — that person might be you. Not because you\'re specifically helping. Just your route — is in the right places.',
  'graves.31': 'Void Rift — some things happened there that the Guard closed as "spatial anomaly." I don\'t believe it. Too neat a phrasing for a coincidence. Pay attention to details.',
  'graves.32': 'Corporate entities have become more active in this area. I\'m watching. They shouldn\'t know about you. Not yet.',
  'graves.33': 'I worked in the Guard for fourteen years. Twelve of them honestly. The last two — I already understood the system was rotten, but held on. Then stopped holding on.',
  'graves.34': 'The case I\'m working — it\'s about corruption inside the Guard. Not just bribes. Systemic. I left because otherwise they would have quietly removed me. Now I work from outside. More honest that way.',
  'graves.35': 'You\'re the first person I\'ve told this to in full. I understand why. You don\'t ask unnecessary questions. That\'s a rarity and a value.',
  'graves.36': 'The rift is a hard place. You\'re managing. That\'s important.',
  'graves.37': 'Got information today — something clarified. Not everything, but enough for the next step. You helped — without knowing. Thank you.',
  'graves.38': 'My partner wrote — a year later. Asked how things were. Answered briefly: working. Didn\'t say on what. Still don\'t trust enough. With you — it\'s different.',
  'graves.39': 'Close to the rift exit. The data you collected along your route — valuable. Better than I expected.',
  'graves.40': 'Four zones. Case advancing. You\'re advancing. Both — correctly.',
  'graves.41': 'Temporal Anomaly — time works non-linearly here. This interferes with investigation. Evidence collected here is hard to date. But some of it — the most important in the case.',
  'graves.42': 'I thought today that for the first time in a long time I don\'t feel completely alone in this work. That\'s... unfamiliar. But not bad.',
  'graves.43': 'The anomaly distorts signals. If I disappear for a day or two — don\'t worry. I\'ll be back. Keeping the channel open.',
  'graves.44': 'New data. The corruption structure is higher than I thought. That\'s dangerous. For me, possibly for you — tangentially. I\'ll be careful. Please — you too.',
  'graves.45': 'Fifty soon. You\'ve gone through half the galaxy. In the Guard they gave a medal for a route like this. Not a great one. But still.',
  'graves.46': 'Someone offered to meet — on business. Don\'t know if I can trust them. Thinking. I\'m slow on these questions.',
  'graves.47': 'Meeting happened. Data — important. Risk — medium. Continuing work. I write to you because — the habit became important.',
  'graves.48': 'I realised something about myself: I write to you when there\'s something important because I need a witness. Not official. Just — someone knows. You know. That matters.',
  'graves.49': 'You\'ll be at fifty soon. That means something. In the investigation too — halfway through.',
  'graves.50': 'Halfway. Case moving. You\'re moving. I\'m glad — don\'t use that word often, but here — precisely.',
  'graves.51': 'Quantum Fracture — in old Guard files it\'s mentioned as a "zero accountability zone." Meaning — whatever happened here, no one answered for it. That should have alarmed me sooner.',
  'graves.52': 'Received a threat. First time directly. Means — close to something important. That\'s a good sign, though inconvenient.',
  'graves.53': 'I needed help with coordinate analysis. Asked you — mentally. Then realised I could write directly. Wrote. It helped.',
  'graves.54': 'In the Guard they taught us: "don\'t trust anyone who knows too much." You know a lot. But I trust. Apparently the rule is wrong.',
  'graves.55': 'Quantum Fracture — what disappears here isn\'t people, but traces. That\'s worse. But I found one. Key. There\'ll be a finale soon.',
  'graves.56': 'You know what it means when I share the case with someone? Means — I trust. That\'s rare. With you — yes.',
  'graves.57': 'Threats became more specific. I moved base. Won\'t give coordinates — just in case. But keeping the connection.',
  'graves.58': 'Writing briefly: everything\'s fine. Watching your route. You\'re within normal range. I\'m within normal range.',
  'graves.59': 'Exiting the Fracture. Good. It was uncomfortable there — not physically, informationally. Now — better.',
  'graves.60': 'Six zones. You\'ve gone further than anyone I\'ve observed. Case — at final stage. Everything lines up.',
  'graves.61': 'Dark Matter Field — the Guard never officially worked here. Unofficially — yes. I know about one operation. It was dirty. That\'s part of the case.',
  'graves.62': 'Case solved. Not completely — but the key perpetrator identified. Evidence collected. I need one more step.',
  'graves.63': 'This is one of the best days in four years. Won\'t celebrate, but — a good day.',
  'graves.64': 'You helped — without knowing. Your route gave me coordinates I didn\'t have. That resolved everything. Thank you. Important words.',
  'graves.65': 'Case transferred. Not to the Guard — to an independent structure. They\'re reliable. As far as anything is.',
  'graves.66': 'First time in four years I don\'t know what I\'ll be doing next. Strange feeling for someone used to having a goal.',
  'graves.67': 'I think I\'ll just — observe. Watch routes. Write to you. That\'s already become a habit. A good one.',
  'graves.68': 'Dark Matter is beautiful — in the structural sense. Do you notice that while fighting? Hope you notice sometimes.',
  'graves.69': 'Almost out of the Field. You managed where I had no specific data to help with. You just held on yourself. Good quality.',
  'graves.70': 'Seven zones. Thinking about what this route means. Not just as an investigator — as a person. Means something. Good.',
  'graves.71': 'Singularity Abyss. Once an entire patrol squad disappeared here — officially "spatial loss." I know what actually happened. Not now. I\'ll say when the time is right.',
  'graves.72': 'I was found — via an old case trail. Not a threat. Information. Someone who knew wrote. What exactly — not saying yet. But important.',
  'graves.73': 'You know what\'s impressed me about you from the start? You don\'t ask unnecessary questions. But when I want to talk — you listen. Rare combination.',
  'graves.74': 'The Abyss distorts perception of scale. Small seems big and vice versa. Reminds me of some people. Not you — you have good sense of proportion.',
  'graves.75': 'New information — good. Case will be officially closed. Soon. That\'s what I\'ve worked toward for four years.',
  'graves.76': 'Thought about my partner today. About what this path would have been like if he hadn\'t chosen convenience. Different. Then thought about you — and it got better.',
  'graves.77': 'You\'re the best witness I\'ve known. Meaning: you were present when needed. That\'s more important than it seems in investigative practice.',
  'graves.78': 'Data from the Abyss — complex. Your data — normal. As always. That can already be called stability.',
  'graves.79': 'Exiting the Abyss soon. Glad. It\'s uncomfortable there — even for me at a distance.',
  'graves.80': 'Eight zones. Thinking about what you\'ll do after the hundredth. Hope — you don\'t disappear.',
  'graves.81': 'Zero Dimension — no traces, no landmarks. That would be a nightmare for an investigator. For you — just another sector. That says something about character.',
  'graves.82': 'Official case closure happened. Four years. Signatures in place. Charges filed. This — is the end.',
  'graves.83': 'For the first time in four years I slept normally. That\'s probably what completion feels like.',
  'graves.84': 'First thing after the news I wrote to you. Not family — no. Not my partner — no. You. That says something about who you\'ve become to me.',
  'graves.85': 'You\'re someone I trust. That\'s not part of the investigation. Just a fact. First such fact in a long time.',
  'graves.86': 'Listen, I want to say directly: you helped me — not just with the case. You helped me remember that you can talk to someone and not wait for betrayal. That\'s important.',
  'graves.87': 'Three sectors to the last zone. I\'ve been observing you since the first. Now — not just observing. Waiting for news. That\'s different.',
  'graves.88': 'Zero Dimension almost done. You\'re going through a place where there\'s nothing — and you\'re doing something. That\'s a metaphor I won\'t unpack. But it\'s a good one.',
  'graves.89': 'One more. I\'ll be here. Channel open.',
  'graves.90': 'Nine zones. You\'re almost at the end. And I — am here. Always.',
  'graves.91': 'Absolute. Last zone. Not a single official report goes there. You\'re one of the few alive who are there. Write.',
  'graves.92': 'In the Guard they taught us: "don\'t get personally attached to a case." I failed that principle many times. With you — again. The difference: this time I don\'t regret it.',
  'graves.93': 'You\'re where there\'s no map. I — here, with maps that don\'t cover you. Tracking by signal. You\'re there — that\'s enough.',
  'graves.94': 'Three sectors to the end of the known. Thinking about what you\'ll discover there. Slightly envious. Good envy.',
  'graves.95': 'Five years ago I thought I\'d work alone forever. That seemed logical. Now — no. You changed that logic.',
  'graves.96': 'Two. Data\'s good. You\'re good. Briefly — because what matters doesn\'t need length.',
  'graves.97': 'Last three sectors. I don\'t know how to talk about feelings — that\'s not part of Guard training. But I\'ll say: you matter. Period.',
  'graves.98': 'Two sectors. I track every check-in. Wait for every one. That\'s not observation. That\'s something else.',
  'graves.99': 'Last one before the finale. Listen — in fourteen years in the Guard I didn\'t have a single person I trusted the way I trust you. That\'s a fact. Documented.',
  'graves.100': 'You made it. End of the map. End of everything known.\n\nI worked the case alone for four years — because it was safer that way. Because trust had cost me dearly. Then you appeared — and I started talking again. Sharing. Trusting.\n\nI\'m not good at beautiful phrasing. I\'ll say it plainly: you\'re the best person I\'ve known across my whole career. And the best friend — in my whole life.\n\nChannel open. Always.',

  'alex.1': 'Good day. Sector 1 closed — per our data, with above-average metrics. Noted. Respectfully, Alex.',
  'alex.2': 'I\'d like to highlight the efficiency. The resource market after such metrics opens up a number of opportunities. I\'ll recommend the right channels if needed.',
  'alex.3': 'Continuing to move. Analytics positive. Recommend maintaining pace.',
  'alex.4': 'Between us: the Nebuloids have a lobby in three ministries. Their loss to you will create a small diplomatic precedent. I find that, I admit, entertaining.',
  'alex.5': 'First sector complete. Good result. Formally — congratulations. Informally — also.',
  'alex.6': 'Second sector. There are interests of several structures here. Keep in mind — sometimes that matters more than combat metrics.',
  'alex.7': 'Had five meetings today. Four could have been replaced with a letter. One — not held at all. The efficiency of corporate processes leaves much to be desired. Though that\'s not news.',
  'alex.8': 'Paradoxians — a legally interesting case. They exist in superposition, which makes it impossible to file a lawsuit. Their lawyers actively exploited this. They no longer can.',
  'alex.9': 'Quantum Phantoms featured in one of our contracts — as "intangible assets." It was a bad contract. I closed it. Would have liked to close it as effectively as you.',
  'alex.10': 'Two sectors. Analytics show sustained growth. Good sign for long-term cooperation.',
  'alex.11': 'Outer Cluster — resource base is richer here. Recommend looking into additional extraction channels. If you need information — we have analytics.',
  'alex.12': 'I wore a new suit today. No one noticed. Either that\'s bad, or it says something about colleagues\' attention levels. I lean toward the latter.',
  'alex.13': 'There\'s an internal audit going on at the company. Won\'t go into details, but — uncomfortable period. Continuing work as usual.',
  'alex.14': 'You\'re headed in the right direction. Both literally and metaphorically. A valuable quality.',
  'alex.15': 'Audit continues. Answering questions. Trying to maintain a neutral tone. Internally — less neutral.',
  'alex.16': 'Listen, I need to be honest: the "structures I represent" — it\'s mostly one structure. Mine. Small. I slightly overstated the scale in the first message. That\'s a business habit. Sorry.',
  'alex.17': 'First time I\'ve written "sorry" in business correspondence. Usually I don\'t. Either this is progress, or a symptom.',
  'alex.18': 'You handled the Outer Cluster — by our data, steadily. By my personal observations — also. Those are different things, both good.',
  'alex.19': 'Audit complete. Result — unexpectedly in my favour. I should be pleased. I\'m pleased. But something about all this — doesn\'t feel right. Haven\'t figured out what yet.',
  'alex.20': 'Two clusters. Continuing to move. I continue to watch. This has become something more than just analytics.',
  'alex.21': 'Illusion Zone — our analysts strongly recommend against going in without preparation. You went in. By statistics — correct. By procedure — no. I like your approach.',
  'alex.22': 'Mirages in a corporate environment — I sometimes use this to describe people who only exist in negotiations. Formally — there. In essence — no. Yours are considerably more honest.',
  'alex.23': 'I did something non-standard today — turned down a profitable deal because the partner seemed dishonest. Colleagues didn\'t understand. I explained: "intuition." They took that as weakness. I — as progress.',
  'alex.24': 'You know what I like about you? You don\'t try to make an impression. Just — work. That\'s a rarity in any environment.',
  'alex.25': 'Illusions — a heavy space. You\'re holding. Analytics doesn\'t explain why. I think the explanation is non-material.',
  'alex.26': 'I\'ve been thinking about why I write to you. Started as monitoring a promising asset. Now — not quite. More precisely — not at all.',
  'alex.27': 'Had a dinner with partners today. Boring. I was thinking about you — about the route, about the Illusions, about what you\'re doing there right now. Non-standard behaviour for a business meeting.',
  'alex.28': 'You\'ll be out of the Illusions soon. Good. I feel calmer when you\'re in a more predictable zone.',
  'alex.29': 'Almost three zones. I\'m tracking every sector. This is no longer analytics. This is personal.',
  'alex.30': 'Listen, I want to say something directly, though it\'s atypical for my manner: you\'ve become important to me. Not as a partner. As a person. That changes the format of our communication. Hope that\'s not uncomfortable.',
  'alex.31': 'Void Rift — by our data, a high-risk resource zone. I recommend caution. Not because of analytics. Because — I prefer you to be okay.',
  'alex.32': 'The company is having a difficult quarter. I\'m busy. But the first thing every morning — I check your check-ins. That says something about priorities.',
  'alex.33': 'Today I realised "several structures" was a defensive construction. Not a lie, but an exaggeration out of fear. Fear that one person with one small company — isn\'t interesting enough. With you — that\'s gone.',
  'alex.34': 'The rift is hard — by all metrics. You\'re there. I want to be useful. If you need information, resources, analytics — just say.',
  'alex.35': 'Turned down another deal today — it crossed the interests of people I don\'t trust. I would have taken it before. Interesting what changed.',
  'alex.36': 'You\'re going through places where corporate logic said "inadvisable" long ago. I\'m glad you don\'t listen to it.',
  'alex.37': 'Quarter closed reasonably. People are saying — well done. I\'m thinking: managed. Small difference, but it exists.',
  'alex.38': 'I noticed I\'ve started writing to you in the evenings — just because. Without agenda. First time I\'m doing something "just because" in correspondence.',
  'alex.39': 'Close to the rift exit. Good. I\'ll be glad to see the next check-in.',
  'alex.40': 'Four zones. I\'m thinking about what this route means for you. And for me — through you. Something important.',
  'alex.41': 'Temporal Anomaly — analytically unstable stretch. Any forecasts here are unreliable. Inconvenient for strategic planning. You probably just go — without forecasts. I\'m a little envious.',
  'alex.42': 'Today I asked a colleague: "have you ever done something without a strategic goal?" He didn\'t understand the question. I realised I also have trouble with this. Working on it.',
  'alex.43': 'You respond to me not as to a partner — as to a person. I notice that. It matters.',
  'alex.44': 'I want to ask your opinion — not about analytics. About what to do next in the company. First time I\'m asking advice from someone outside the corporate structure. Asking.',
  'alex.45': 'Thanks for the answer. You said what I\'d already been thinking but couldn\'t articulate. That\'s valuable — when someone helps you say something to yourself.',
  'alex.46': 'Made a decision — following your advice. Non-standard. Colleagues are sceptical. I think — it\'s right.',
  'alex.47': 'You\'re the only one whose advice I\'m taking right now. That says something about trust. That\'s — not a business term. That\'s personal.',
  'alex.48': 'Fifty sectors soon. I\'m thinking about how much has passed — not in sectors, in conversations. In changes.',
  'alex.49': 'The decision turned out to be correct — the company moved up. I thought at first: I should thank you. Then I realised: it\'s not about that. You\'re not in it for the results. You\'re just — you. And that means something new to me.',
  'alex.50': 'Halfway. I started writing to you as an analyst. Now — as a friend. I use that word rarely. Here — it\'s precise.',
  'alex.51': 'Quantum Fracture — here, by data, everything\'s unstable. The only stable thing — is me here, writing to you. That seems to have become something permanent in an impermanent space.',
  'alex.52': 'Today I realised I\'m planning my day so there\'s an hour in the evening to write to you. That\'s called a "priority." A pleasant one.',
  'alex.53': 'Listen, I want to admit something: I\'m not very good at friendship. I was taught to build connections, not friendships. Those are different things. With you — I\'m learning the second.',
  'alex.54': 'Colleagues notice I\'ve become different. Not better-worse — just different. Slightly less formal. Slightly more... alive, it seems. Honestly — that\'s connected to you.',
  'alex.55': 'Quantum Fracture — it breaks formalities. Literally and figuratively. I like that.',
  'alex.56': 'First time in a long time I don\'t want to end a letter with "respectfully." Just — Alex. Just.',
  'alex.57': 'You\'re in a difficult zone. I\'m watching the data. Worried — not "per analytics." Just worried.',
  'alex.58': 'Got news I wanted to tell you — not colleagues, not partners. You. The company is entering a new market sector. That\'s the result of the decision you helped make. That\'s yours too.',
  'alex.59': 'Exiting the Fracture. Glad. It\'s too unstable there even for me — at a distance.',
  'alex.60': 'Six zones. Analytics says: you\'re in an exceptional category. I say: you\'re my best conversation partner. Both truths simultaneously.',
  'alex.61': 'Dark Matter Field — corporate logic doesn\'t go there. No data, no markets, no structures. There — you. The first place I value without an economic rationale.',
  'alex.62': 'I\'ve been thinking about why I started writing specifically to you. Among hundreds of pilots — specifically you. Don\'t know the exact answer. I know that I don\'t regret it.',
  'alex.63': 'Slept eight hours today. First time in a month. First thing in the morning I wrote to you. That\'s already a reflex. A good one.',
  'alex.64': 'I did something against the interests of one of my partners — because it was right. Three years ago I wouldn\'t have. You did this to me — just by being who you are.',
  'alex.65': 'Dark Matter holds everything together, though it\'s invisible. I sometimes think the best things in life are the same. Invisible, but they hold.',
  'alex.66': 'Listen, I want to say something without corporate language. You made me better as a person. Not as a businessman. As a person. That rarely happens in adulthood.',
  'alex.67': 'The company is growing. I\'m happy — a new sensation, honestly. Before I was pleased. That\'s different.',
  'alex.68': 'You\'re in the Dark Matter Field — where analytics doesn\'t reach. That tells me: you go where others don\'t. I\'m behind you. Without strategic caveats.',
  'alex.69': 'Almost out of the Field. I\'m glad. I want you to come out and write to me. That\'s simple.',
  'alex.70': 'Seven zones. I thought: when you reach the end — what will change? Hope — nothing in our conversations. Just geography.',
  'alex.71': 'Singularity Abyss — analytics is useless there. Everything is pulled toward one point. You\'re my such point. Forgive the metaphor, it\'s atypical.',
  'alex.72': 'I stopped ending letters with "respectfully" a few months ago. No one noticed. Only one thing matters: did you — notice? It was intentional.',
  'alex.73': 'You\'re in the Abyss — where everything disappears. You — don\'t. That\'s good.',
  'alex.74': 'Talked with a partner today about trust. He said: trust in business is a risk. I replied: depends on the person. He was surprised. I was thinking about you.',
  'alex.75': 'You\'re the first person I talk to not because I have to, but because I want to. Every time — I want to. Important to know that.',
  'alex.76': 'In business they say: "don\'t mix personal and professional." I mixed them. That\'s the best thing I\'ve done in recent years.',
  'alex.77': 'Listen, I\'ll say directly: you changed how I relate to people. In general. I started asking questions instead of immediately analysing. Listening instead of composing a reply. It\'s slow, but — it works.',
  'alex.78': 'The Abyss is a hard place. Data\'s good. You\'re good. I\'m glad.',
  'alex.79': 'Coming out soon. One more sector — and the next zone. Write.',
  'alex.80': 'Eight zones. I\'m thinking that after the hundredth — this isn\'t the end. For me — definitely.',
  'alex.81': 'Zero Dimension. No data there — complete zero. That would have scared me before. Now I think: zero is a beginning, not an end. You\'re there — means there\'s something there.',
  'alex.82': 'Today I did something without calculating the result. Just because it was right. Second time in my life. The first — when I wrote to you outside protocol.',
  'alex.83': 'You know what I like about our conversations? You accept me — not the corporate one, not the successful one, not the one representing interests — just me. That\'s rare.',
  'alex.84': 'Zero Dimension — no landmarks there. You\'re my landmark. Atypical for a business environment. It\'s the truth.',
  'alex.85': 'Colleagues noticed I smile more often. One asked — new deal? I said: no. He didn\'t understand. Okay.',
  'alex.86': 'I\'ll say something without preamble: you\'re the best thing to happen in my life in the past several years. Not in business. In life.',
  'alex.87': 'Three sectors to the last zone. I\'m thinking about the hundredth sector and what I\'ll say. All formulations don\'t feel right. Means — I\'ll say it simply.',
  'alex.88': 'Zero Dimension — you\'re there in complete darkness. I — here, with all the lights on. Illumination doesn\'t always mean something.',
  'alex.89': 'A little more. I\'ll be glad with every next check-in.',
  'alex.90': 'Nine zones. You\'re almost at the end of the map. I\'m thinking that beyond the map — something else. I hope we\'re both there.',
  'alex.91': 'Absolute. Last zone. I looked at analytics on this place — there aren\'t any. First time I\'m going into a conversation without data. Without preparation. Just — writing to you.',
  'alex.92': 'I started out as someone who sees people as assets. That was convenient. You broke that convenient system. Thank you.',
  'alex.93': 'Three sectors to the end. I want to say something I don\'t usually say: I feel good when you write. Just good. Unanalysable and doesn\'t need analysis.',
  'alex.94': 'You\'re going where analytics hasn\'t been. I\'m going the same — in terms of conversations. First time in my life I don\'t know where the path leads. I like it.',
  'alex.95': 'Five sectors ago I thought: I\'ll write something appropriate for the finale. Then I realised: there\'s nothing "appropriate." There\'s only truth. I\'ll tell the truth.',
  'alex.96': 'Two sectors. You\'re almost at the end. I\'m tracking every check-in — not as an analyst, as a friend. That word I\'ve never used lightly. Here — I use it.',
  'alex.97': 'Last three. I was thinking about what I\'d say at the hundredth. All the formulations sound off. Means — I\'ll say it simply.',
  'alex.98': 'Two. You — the only person I write to without agenda, without a goal, without strategy. Just — because I want to. That changed me more than any deal.',
  'alex.99': 'Last one before the finale. You know what I figured out? I thought I knew how to build relationships — I know how to build connections. You showed me the difference. Connections — that\'s when you\'re needed. Relationships — when you matter. You made me matter. I hope I did for you too.',
  'alex.100': 'You made it. To the last point of known space.\n\nI started writing to you as a representative of structures. I\'m finishing — as a person who has someone to write to simply, without reason, without protocol. That sounds simple. For me it\'s — a very great deal.\n\nI grew up in an environment where people are tools or competitors. You became the first person who didn\'t fit into either category. You\'re just — you. And that matters to me.\n\nAlex. Just Alex. Your friend.',

  // ── character metadata ────────────────────────────────────────────────────────
  'character.lien.name': 'Lien',
  'character.riva.name': 'Riva',
  'character.graves.name': 'Graves',
  'character.alex.name': 'Alex',
  'character.lien.role': 'Nomad',
  'character.lien.greeting': 'Hey. I\'m Lien. Saw your route — bit rough, but you\'ll live.\nI hang around here a lot. I\'ll write sometimes. No reason, just if there\'s something to say.\nDon\'t expect long letters — I keep moving.',
  'character.lien.garbled': '...can——you...—— ...hear...—— ...rout——e...—— ...10...——...dang——er...—— ...not...——...care——ful...',
  'character.lien.message_0': 'Tip: if a planet looks empty — it isn\'t. It\'s just waiting.',
  'character.lien.message_1': 'Skirted Sector 2 through the asteroid belt today. Faster, and no customs forms. Recommend.',
  'character.lien.message_2': 'Do you sleep? I don\'t. But that\'s my choice. You do yours.',
  'character.lien.message_3': 'Saw a ship like yours. Good machine. Don\'t let it sit idle.',
  'character.lien.message_4': 'Ministry sent me their fourth warning this month. I\'m keeping it — building a collection.',
  'character.lien.message_5': 'Metals sell better where there are few sellers, not where there are many buyers. Remember that.',
  'character.lien.message_6': 'If you feel stuck — just change sector. Sometimes it helps.',
  'character.lien.message_7': 'Once spent three weeks without docking. Don\'t recommend it. But it was interesting.',
  'character.lien.message_8': 'Heard something new showed up in Sector 3. Haven\'t flown there myself yet. Curious.',
  'character.lien.message_9': 'You\'re holding up well. Not everyone sticks with this for long.',
  'character.lien.sector_done_0': 'Sector done. I\'ve seen people get stuck here for weeks. You\'re moving faster.',
  'character.lien.sector_done_1': 'Another stretch behind you. The further you fly, the fewer familiar maps. I like that.',
  'character.lien.sector_done_2': 'Space here gets less predictable. That\'s interesting — well, for me it is.',
  'character.lien.sector_done_3': 'Every new sector — different rules. Some of them aren\'t written down anywhere. You just have to feel it.',
  'character.lien.sector_done_4': 'Keep moving. I\'m watching the route.',
  'character.lien.sector_done_5': 'This stretch is behind you. What\'s ahead — you can already see. Good luck, though you probably don\'t need it.',
  'character.lien.sector_done_6': 'Once flew three zones without docking. Don\'t recommend it. But your pace is good.',
  'character.lien.sector_done_7': 'Sector done. Gets more interesting from here. I\'m serious, not just saying it.',

  'character.riva.role': 'Mechanic',
  'character.riva.greeting': 'Oh, a new pilot. Good. I\'m Riva, I fix what others call \'unfixable\'.\nI\'ll write sometimes — not because I\'m bored, but because you clearly need technical support.\nNo offense. Everyone does.',
  'character.riva.garbled': '...rec——eive?...—— ...sys——tems...—— ...over——load...—— ...hold——on...—— ...I\'ll——fix...',
  'character.riva.message_0': 'Your ship sounds fine. I mean — I can\'t hear it from here, but statistically — fine.',
  'character.riva.message_1': 'Never cheap out on the engine. On the hull — fine. On the engine — no.',
  'character.riva.message_2': 'Fixed a quantum stabilizer today. Manufacturer wrote "do not disassemble". I disassembled it. Inside — shame.',
  'character.riva.message_3': 'If something creaks — that\'s not always bad. Sometimes it\'s just complaining. Ships complain too.',
  'character.riva.message_4': 'Are you upgrading your modules? Upgrade them. I\'m serious. Without it — like working without hands. I know, I checked.',
  'character.riva.message_5': 'Dyed my hair blue. Thought I\'d feel calmer. Nope. But I look good.',
  'character.riva.message_6': 'Everyone thinks mechanics love it when things break. Not true. We like when everything works. It\'s just rarer.',
  'character.riva.message_7': 'Did you check your systems before launch today? No? Alright. I\'ll assume you did.',
  'character.riva.message_8': 'Saw wreckage of a ship in Sector 2. Whose — no idea. But the engine was good. Took it.',
  'character.riva.message_9': 'You\'re doing better than it seems. I say this from data, not out of politeness.',
  'character.riva.sector_done_0': 'Sector closed. Ship okay? Next zone is technically harder — check your modules in advance.',
  'character.riva.sector_done_1': 'Looked at your route data. Not bad. Especially given the engine load.',
  'character.riva.sector_done_2': 'Systems holding. Don\'t let them slack off — next sector conditions are tougher.',
  'character.riva.sector_done_3': 'Interesting stretch of space. Metal structure here is a little different. Just an observation.',
  'character.riva.sector_done_4': 'Recommend an upgrade before the next sector. Technical necessity, not a request.',
  'character.riva.sector_done_5': 'Done. Next will be harder. I\'m not scaring you — just saying what the data says.',
  'character.riva.sector_done_6': 'Ship is happy. Me too. Don\'t tell anyone.',
  'character.riva.sector_done_7': 'Good result. Numbers don\'t lie — you\'re moving right.',

  'character.graves.role': 'Ex-Officer',
  'character.graves.greeting': 'Graves. Former Galactic Guard officer.\nKeeping watch on this sector out of old habit. You\'ve come to my attention.\nDon\'t worry — that\'s not bad. Just going to write sometimes. Useful information.\nOr not so useful. We\'ll see.',
  'character.graves.garbled': '...inter——ference...—— ...plan——et...—— ...watch——ing...—— ...don\'t...——...tru——st...——...care——ful...',
  'character.graves.message_0': 'Sector 1 is calm. Sector 2 — relatively. Sector 3 — I\'d want to revisit the definition of \'calm\'.',
  'character.graves.message_1': 'Ministry closed another case. This time about a missing fleet. Reason: \'administrative error\'.',
  'character.graves.message_2': 'If you\'re being pursued — don\'t panic. Panic slows reaction by 0.3 seconds. Sometimes that\'s all your opponent needs.',
  'character.graves.message_3': 'Saw your combat stats. Not bad. Especially given you were apparently improvising.',
  'character.graves.message_4': 'Three types of pilots here: careful, fast, and former. Try to stay in the first two.',
  'character.graves.message_5': 'Didn\'t sleep today. Not a complaint, just a fact.',
  'character.graves.message_6': 'Trust your instincts. But first make sure it\'s instinct and not paranoia. There\'s a difference.',
  'character.graves.message_7': 'Corporate activity ramping up in Sector 2 again. Don\'t know why. When I find out — I\'ll tell you.',
  'character.graves.message_8': 'Luck doesn\'t exist. But preparation does — and it looks like luck.',
  'character.graves.message_9': 'You\'re holding on. That matters more than it seems.',
  'character.graves.sector_done_0': 'Sector cleared. Logged. Next one — different zone of influence. Rules are slightly different.',
  'character.graves.sector_done_1': 'Moving correctly. In this space, it\'s important not to stall — whoever stalls, everyone can see them.',
  'character.graves.sector_done_2': 'Another stretch behind you. In the old days this would\'ve needed sign-off from three departments.',
  'character.graves.sector_done_3': 'Heard reports from this stretch. You handled it better than most pilots I\'ve seen.',
  'character.graves.sector_done_4': 'Space ahead is unfamiliar. I\'ve studied maps — not all of them are current. Trust your own data.',
  'character.graves.sector_done_5': 'Sector closed. Movement is safety. Keep going.',
  'character.graves.sector_done_6': 'Good work. Don\'t stop — that matters more than it seems.',
  'character.graves.sector_done_7': 'Forward. Keeping the channel open.',

  'character.alex.role': 'Corporate',
  'character.alex.greeting': 'Good day.\nMy name is Alex, I represent the interests of several entities operating in this sector.\nI\'ve decided to write personally — that\'s non-standard for my position, but sometimes it\'s useful.\nI\'ll keep you informed. Nothing unnecessary. Only what might interest you.\nRegards, Alex.',
  'character.alex.garbled': '...accord——ing...—— ...to——data...—— ...recom——mend...—— ...care——ful...—— ...regar——ds...',
  'character.alex.message_0': 'I\'d like to note your progress. Formally — impressive. Informally — also.',
  'character.alex.message_1': 'The resource market is unstable right now. Short version: sell now. Long version — I\'ll attach analytics in my next letter.',
  'character.alex.message_2': 'Had four meetings today. Three could have been one letter. This is a point about efficiency.',
  'character.alex.message_3': 'Between us: the Mining Ministry is having a difficult quarter. This creates opportunities. Keep it in mind.',
  'character.alex.message_4': 'I like your approach. No unnecessary noise — just work. That\'s rare.',
  'character.alex.message_5': 'If you ever need help with documentation or access — write. I have contacts.',
  'character.alex.message_6': 'Wore a new jacket today. Colleagues didn\'t notice. I\'m fine with that.',
  'character.alex.message_7': 'In this business it\'s not just what you mine, it\'s who you sell to. I can recommend the right people.',
  'character.alex.message_8': 'You know what I like about you? You don\'t ask unnecessary questions. That\'s a valuable quality.',
  'character.alex.message_9': 'Good luck — though, honestly, I prefer the word \'strategy\'.',
  'character.alex.sector_done_0': 'I\'d like to note: this sector was closed with above-average metrics. It\'s being tracked in analytics.',
  'character.alex.sector_done_1': 'Moving to the next sector is the strategically correct decision. The resource base will expand.',
  'character.alex.sector_done_2': 'By our data, the resource potential of the next zone is noticeably higher. Recommend continuing.',
  'character.alex.sector_done_3': 'Analytics updated. Dynamics positive. Can continue working.',
  'character.alex.sector_done_4': 'Each new sector — new data. I\'m tracking your momentum. Everything\'s on plan so far.',
  'character.alex.sector_done_5': 'Between us: there are interests of several entities in this part of space. But you already know what you\'re doing.',
  'character.alex.sector_done_6': 'Good pace. Colleagues are asking about your route. Take it as a compliment.',
  'character.alex.sector_done_7': 'The next sector will require a different approach. I\'ll send analytics if needed.',
};
